// WF-06 privacy gate — emits ONLY room + times + status. Customer titles are never read.
const location = 'karlskrona';
const list_id  = '901218538075';

const out = [];
for (const item of $input.all()) {
  for (const t of (item.json.tasks || [])) {
    if (!t.start_date || !t.due_date) continue; // no times = not a bookable block

    // Room field — matches 'Rum' (real Pot) or 'Room' (test), case-insensitive
    const rf = (t.custom_fields || []).find(f => /^(rum|room)$/i.test(f.name || ''));
    let room = null;
    if (rf && rf.value !== undefined && rf.value !== null && rf.value !== '') {
      const opts = (rf.type_config && rf.type_config.options) || [];
      const v = rf.value;
      let opt = opts.find(o => String(o.orderindex) === String(v)) // dropdown value = orderindex
             || opts.find(o => o.id === v)                          // fallback: value is option id
             || (typeof v === 'number' ? opts[v] : null);          // fallback: array index
      room = opt ? opt.name : null;
    }

    // Status — ClickUp returns an object {status, type, ...}; store the lowercased name
    const status = (t.status && t.status.status)
      ? String(t.status.status).toLowerCase().trim()
      : null;

    out.push({ json: {
      source_task_id: t.id,
      location,
      list_id,
      room,
      status,
      start_ms: Number(t.start_date),
      end_ms: Number(t.due_date),
      date_updated_ms: Number(t.date_updated),
    } });
  }
}
return out;

