INSERT INTO availability_sanitized (source_task_id, location, room, status, start_ts, end_ts, last_synced_at)
VALUES ('{{ $json.source_task_id }}', '{{ $json.location }}', NULLIF('{{ $json.room }}',''), NULLIF('{{ $json.status }}',''), to_timestamp({{ $json.start_ms }}/1000.0), to_timestamp({{ $json.end_ms }}/1000.0), now())
ON CONFLICT (source_task_id) DO UPDATE SET location=EXCLUDED.location, room=EXCLUDED.room, status=EXCLUDED.status, start_ts=EXCLUDED.start_ts, end_ts=EXCLUDED.end_ts, last_synced_at=now();
UPDATE sync_state SET last_run_ms = GREATEST(last_run_ms, {{ $json.date_updated_ms }}) WHERE list_id = '{{ $json.list_id }}';

